function padLabel(text, targetLength, padString) {
  const filler = padString === undefined ? '0' : padString;
  if (text.length >= targetLength) return text;
  if (filler === '') return text;
  return filler.repeat(Math.ceil((targetLength - text.length) / filler.length)) + text;
}
module.exports = { padLabel };

