const test = require('node:test');
const assert = require('node:assert/strict');
const { padLabel } = require('../src/left-padding.cjs');

test("omitted padding means spaces rather than zeros", () => {
  assert.equal(padLabel('Q7', 5), '   Q7');
  assert.equal(padLabel('Q7', 5, undefined), '   Q7');
});

test("padding repeats then truncates at the end of the filler", () => {
  assert.equal(padLabel('Q7', 7, 'ab'), 'ababaQ7');
  assert.equal(padLabel('Q7', 4, 'wxyz'), 'wxQ7');
  assert.equal(padLabel('Q7', 7, ''), 'Q7');
});

test("strings already long enough are unchanged", () => {
  assert.equal(padLabel('Cedar', 3, '0'), 'Cedar');
  assert.equal(padLabel('Q7', 2, '0'), 'Q7');
  assert.equal(padLabel('Q7', 0, '0'), 'Q7');
});

test("length and truncation use UTF-16 code units", () => {
  assert.equal(padLabel('😀', 3, '0'), '0😀');
  assert.equal(padLabel('😀', 2, '0'), '😀');
  assert.equal(padLabel('Q', 2, '😀'), '\ud83dQ');
});

